def encode(message):
    encoded_message = []
    vowels = 'aeiouAEIOU'

    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                new_char = char.upper()
            else:
                new_char = char.lower()

            # Replace vowels
            if new_char in vowels:
                new_char = chr(ord(new_char) + 2)

            encoded_message.append(new_char)
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)
